-- More restaurants for every food type (ids 115-170) with their menus, plus a
-- rating, delivery time and village for every restaurant. Same data as
-- src/data/moreRestaurants.ts (keep the two in step).
-- Safe to run again: rows are upserted by id / (scope, product_id).

alter table public.shops add column if not exists rating numeric(2,1);
alter table public.shops add column if not exists delivery_time text;
alter table public.shops add column if not exists village text;

on conflict (id) do update set emoji = excluded.emoji, name = excluded.name, description = excluded.description,
  open = excluded.open, time = excluded.time, bg_color = excluded.bg_color, kind = excluded.kind, food_types = excluded.food_types,
  photo = excluded.photo, rating = excluded.rating, delivery_time = excluded.delivery_time, village = excluded.village;

update public.shops set rating = 4.8, delivery_time = '15-25 دقيقة', village = 'منية سندوب' where id = 101;
